--

CREATE TABLE `anniversary_events` (
  `id` int(11) NOT NULL,
  `name_zh` varchar(100) NOT NULL,
  `name_en` varchar(150) DEFAULT NULL,
  `name_ja` varchar(100) DEFAULT NULL,
